func NewTerminologyValue(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) (TerminologyValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	// Reference: https://github.com/hashicorp/terraform-plugin-framework/issues/521
	ctx := context.Background()

	for name, attributeType := range attributeTypes {
		attribute, ok := attributes[name]

		if !ok {
			diags.AddError(
				"Missing TerminologyValue Attribute Value",
				"While creating a TerminologyValue value, a missing attribute value was detected. "+
					"A TerminologyValue must contain values for all attributes, even if null or unknown. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("TerminologyValue Attribute Name (%s) Expected Type: %s", name, attributeType.String()),
			)

			continue
		}

		if !attributeType.Equal(attribute.Type(ctx)) {
			diags.AddError(
				"Invalid TerminologyValue Attribute Type",
				"While creating a TerminologyValue value, an invalid attribute value was detected. "+
					"A TerminologyValue must use a matching attribute type for the value. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("TerminologyValue Attribute Name (%s) Expected Type: %s\n", name, attributeType.String())+
					fmt.Sprintf("TerminologyValue Attribute Name (%s) Given Type: %s", name, attribute.Type(ctx)),
			)
		}
	}

	for name := range attributes {
		_, ok := attributeTypes[name]

		if !ok {
			diags.AddError(
				"Extra TerminologyValue Attribute Value",
				"While creating a TerminologyValue value, an extra attribute value was detected. "+
					"A TerminologyValue must not contain values beyond the expected attribute types. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Extra TerminologyValue Attribute Name: %s", name),
			)
		}
	}

	if diags.HasError() {
		return NewTerminologyValueUnknown(), diags
	}

	groupAttribute, ok := attributes["group"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`group is missing from object`)

		return NewTerminologyValueUnknown(), diags
	}

	groupVal, ok := groupAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`group expected to be basetypes.StringValue, was: %T`, groupAttribute))
	}

	jobAttribute, ok := attributes["job"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`job is missing from object`)

		return NewTerminologyValueUnknown(), diags
	}

	jobVal, ok := jobAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`job expected to be basetypes.StringValue, was: %T`, jobAttribute))
	}

	taskAttribute, ok := attributes["task"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`task is missing from object`)

		return NewTerminologyValueUnknown(), diags
	}

	taskVal, ok := taskAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`task expected to be basetypes.StringValue, was: %T`, taskAttribute))
	}

	if diags.HasError() {
		return NewTerminologyValueUnknown(), diags
	}

	return TerminologyValue{
		Group: groupVal,
		Job:   jobVal,
		Task:  taskVal,
		state: attr.ValueStateKnown,
	}, diags
}

func NewTerminologyValueMust(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) TerminologyValue {
	object, diags := NewTerminologyValue(attributeTypes, attributes)

	if diags.HasError() {
		// This could potentially be added to the diag package.
		diagsStrings := make([]string, 0, len(diags))

		for _, diagnostic := range diags {
			diagsStrings = append(diagsStrings, fmt.Sprintf(
				"%s | %s | %s",
				diagnostic.Severity(),
				diagnostic.Summary(),
				diagnostic.Detail()))
		}

		panic("NewTerminologyValueMust received error(s): " + strings.Join(diagsStrings, "\n"))
	}

	return object
}

func (t TerminologyType) ValueFromTerraform(ctx context.Context, in tftypes.Value) (attr.Value, error) {
	if in.Type() == nil {
		return NewTerminologyValueNull(), nil
	}

	if !in.Type().Equal(t.TerraformType(ctx)) {
		return nil, fmt.Errorf("expected %s, got %s", t.TerraformType(ctx), in.Type())
	}

	if !in.IsKnown() {
		return NewTerminologyValueUnknown(), nil
	}

	if in.IsNull() {
		return NewTerminologyValueNull(), nil
	}

	attributes := map[string]attr.Value{}

	val := map[string]tftypes.Value{}

	err := in.As(&val)

	if err != nil {
		return nil, err
	}

	for k, v := range val {
		a, err := t.AttrTypes[k].ValueFromTerraform(ctx, v)

		if err != nil {
			return nil, err
		}

		attributes[k] = a
	}

	return NewTerminologyValueMust(TerminologyValue{}.AttributeTypes(ctx), attributes), nil
}

