type TerminologyValue struct {
	Group basetypes.StringValue `tfsdk:"group"`
	Job   basetypes.StringValue `tfsdk:"job"`
	Task  basetypes.StringValue `tfsdk:"task"`
	state attr.ValueState
}

func (v TerminologyValue) ToTerraformValue(ctx context.Context) (tftypes.Value, error) {
	attrTypes := make(map[string]tftypes.Type, 3)

	var val tftypes.Value
	var err error

	attrTypes["group"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["job"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["task"] = basetypes.StringType{}.TerraformType(ctx)

	objectType := tftypes.Object{AttributeTypes: attrTypes}

	switch v.state {
	case attr.ValueStateKnown:
		vals := make(map[string]tftypes.Value, 3)

		val, err = v.Group.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["group"] = val

		val, err = v.Job.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["job"] = val

		val, err = v.Task.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["task"] = val

		if err := tftypes.ValidateValue(objectType, vals); err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		return tftypes.NewValue(objectType, vals), nil
	case attr.ValueStateNull:
		return tftypes.NewValue(objectType, nil), nil
	case attr.ValueStateUnknown:
		return tftypes.NewValue(objectType, tftypes.UnknownValue), nil
	default:
		panic(fmt.Sprintf("unhandled Object state in ToTerraformValue: %s", v.state))
	}
}

func (v TerminologyValue) IsNull() bool {
	return v.state == attr.ValueStateNull
}

func (v TerminologyValue) IsUnknown() bool {
	return v.state == attr.ValueStateUnknown
}

func (v TerminologyValue) String() string {
	return "TerminologyValue"
}

func (v TerminologyValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	attributeTypes := map[string]attr.Type{
		"group": basetypes.StringType{},
		"job":   basetypes.StringType{},
		"task":  basetypes.StringType{},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"group": v.Group,
			"job":   v.Job,
			"task":  v.Task,
		})

	return objVal, diags
}

func (v TerminologyValue) Equal(o attr.Value) bool {
	other, ok := o.(TerminologyValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.Group.Equal(other.Group) {
		return false
	}

	if !v.Job.Equal(other.Job) {
		return false
	}

	if !v.Task.Equal(other.Task) {
		return false
	}

	return true
}

